#!/bin/sh
# AgentGuard endpoint one-click __AG_ACTION__ (Linux / macOS), generated by the AgentGuard server.
#
#   curl -fsSL __AG_URL__/v1/agents/install.sh | sh          # install   (machine scope: | sudo sh)
#   curl -fsSL __AG_URL__/v1/agents/uninstall.sh | sh        # uninstall (machine scope: | sudo sh)
#
# Downloads the client from the server into a temporary directory and runs it:
#   setup      installs hooks for the agents configured in the console (Devices > Client deployment),
#              applies for enrollment, waits for approval and runs a self-test;
#   uninstall  removes AgentGuard hooks of all agents, client files and the host token.
# Linux x86_64 uses the prebuilt binary when the server publishes one, otherwise python3 (3.8+).
set -eu
AG_URL="__AG_URL__"
AG_SCOPE="__AG_SCOPE__"
AG_ACTION="__AG_ACTION__"
AG_BINARY="__AG_LINUX_BINARY__"

say() { printf '%s\n' "$*" >&2; }

# The client talks to the server directly (no proxy); downloads do the same.
fetch() {
    if command -v curl >/dev/null 2>&1; then
        curl -fsSL --noproxy '*' -o "$2" "$1"
    elif command -v wget >/dev/null 2>&1; then
        wget -q --no-proxy -O "$2" "$1"
    elif command -v python3 >/dev/null 2>&1; then
        python3 -c 'import sys, urllib.request as u
u.install_opener(u.build_opener(u.ProxyHandler({})))
u.urlretrieve(sys.argv[1], sys.argv[2])' "$1" "$2"
    else
        say "error: curl, wget or python3 is required to download the client"
        exit 1
    fi
}

if [ "$AG_ACTION" = setup ] && [ "$AG_SCOPE" = machine ] && [ "$(id -u)" != 0 ]; then
    say "error: the deployment is machine-wide (all users); run as root:"
    say "  curl -fsSL $AG_URL/v1/agents/install.sh | sudo sh"
    exit 1
fi

tmp=$(mktemp -d 2>/dev/null || mktemp -d -t agentguard)
trap 'rm -rf "$tmp"' EXIT
trap 'exit 130' INT TERM
if [ "$(uname -s)" = Linux ] && [ "$(uname -m)" = x86_64 ] && [ -n "$AG_BINARY" ]; then
    fetch "$AG_URL/v1/agents/client/$AG_BINARY" "$tmp/client.tar.gz"
    tar -xzf "$tmp/client.tar.gz" -C "$tmp"
    set -- "$tmp/agentguard-endpoint/agentguard-endpoint"
else
    py=$(command -v python3 || true)
    if [ -z "$py" ] || ! "$py" -c 'import sys; sys.exit(sys.version_info < (3, 8))'; then
        say "error: python3 3.8+ is required on this platform ($(uname -s) $(uname -m))"
        exit 1
    fi
    fetch "$AG_URL/v1/agents/client/agentguard-endpoint.tar.gz" "$tmp/client.tar.gz"
    tar -xzf "$tmp/client.tar.gz" -C "$tmp"
    set -- "$py" "$tmp/agentguard-endpoint/agentguard-endpoint.py"
fi
if [ "$AG_ACTION" = setup ]; then
    set -- "$@" setup --url "$AG_URL"
else
    set -- "$@" uninstall --all --purge --url "$AG_URL"
fi
# Piped into sh, stdin is this script: read prompts (enrollment key, Ctrl+C) from the terminal instead.
# Probe in a subshell: a failed redirection on a special builtin would abort a POSIX shell.
if ( : </dev/tty ) 2>/dev/null; then
    "$@" </dev/tty
else
    "$@" </dev/null
fi
